def normalize(x):
 if isinstance(x,str):return x.replace('\\u0027',"'").replace('\\u2032','′')
 if isinstance(x,list):return [normalize(y) for y in x]
 if isinstance(x,dict):return {k:normalize(v) for k,v in x.items()}
 return x
